import java.util.*

fun main() {
    val k = readLine()!!.toInt()
    val times = mutableMapOf<Int, MutableList<Int>>()
    repeat(4) { row ->
        val line = readLine()!!
        for (col in 0..3) {
            val c = line[col]
            if (c != '.') {
                val t = c - '0'
                times.getOrPut(t) { mutableListOf() }.add(row * 4 + col)
            }
        }
    }
    for ((t, panels) in times) {
        val n = panels.size
        if (n > 2 * k) {
            println("NO")
            return
        }
        val sorted = panels.sorted()
        var possible = false
        for (i in 0..n) {
            val left = if (i > 0) sorted[i - 1] - sorted[0] + 1 else 0
            val right = if (i < n) sorted[n - 1] - sorted[i] + 1 else 0
            if (left <= k && right <= k) {
                possible = true
                break
            }
        }
        if (!possible) {
            println("NO")
            return
        }
    }
    println("YES")
}
