import java.util.*

fun main() {
    val k = readLine()!!.toInt()
    val panels = Array(4) { readLine()!!.toCharArray() }
    val times = mutableMapOf<Int, MutableList<Pair<Int, Int>>>()
    for (i in 0..3) {
        for (j in 0..3) {
            val c = panels[i][j]
            if (c != '.') {
                val t = c - '0'
                times.getOrPut(t) { mutableListOf() }.add(Pair(i, j))
            }
        }
    }
    var possible = true
    for ((t, list) in times) {
        val n = list.size
        if (n > 2 * k) {
            possible = false
            break
        }
        val visited = BooleanArray(n)
        var groups = 0
        for (i in 0 until n) {
            if (!visited[i]) {
                groups++
                visited[i] = true
                for (j in i + 1 until n) {
                    if (!visited[j] && list[i].first == list[j].first) {
                        visited[j] = true
                        if (groups < k) {
                            groups++
                        } else {
                            possible = false
                            break
                        }
                    }
                }
                if (!possible) break
            }
        }
        if (!possible) break
    }
    println(if (possible) "YES" else "NO")
}
